ViewModel:
```swift
import Foundation

class ChatViewModel: ObservableObject {
    @Published var userInput = ""
    @Published var response = ""
    @Published var isLoading = false
    @Published var errorMessage: String?

    // Replace with your actual API endpoint and key
    private let apiUrl = "https://api.example.com/v1/chat/completions" // e.g., your self-hosted endpoint
    private let apiKey = "YOUR_API_KEY" // Store securely, not in code!

    func sendMessage() async {
        guard !userInput.trimmingCharacters(in: .whitespaces).isEmpty else { return }

        isLoading = true
        errorMessage = nil
        response = ""

        defer { isLoading = false }

        do {
            var request = URLRequest(url: URL(string: apiUrl)!)
            request.httpMethod = "POST"
            request.setValue("application/json", forHTTPHeaderField: "Content-Type")
            request.setValue("Bearer \(apiKey)", forHTTPHeaderField: "Authorization")

            let body: [String: Any] = [
                "model": "vicuna-13b-v1.5", // adjust as per your endpoint
                "messages": [
                    ["role": "user", "content": userInput]
                ],
                "max_tokens": 512
            ]

            let jsonData = try JSONSerialization.data(withJSONObject: body)
            request.httpBody = jsonData

            let (data, _) = try await URLSession.shared.data(for: request)
            let json = try JSONSerialization.jsonObject(with: data) as? [String: Any]

            // Parse response - structure depends on API
            if let choices = json?["choices"] as? [[String: Any]],
               let firstChoice = choices.first,
               let message = firstChoice["message"] as? [String: Any],
               let content = message["content"] as? String {
                response = content
            } else {
                throw NSError(domain: "ResponseError", code: 1, userInfo: [NSLocalizedDescriptionKey: "Invalid response format"])
            }
        } catch {
            errorMessage = "Error: \(error.localizedDescription)"
        }
    }
}
```

SwiftUI View:
```swift
import SwiftUI

struct ChatView: View {
    @StateObject private var viewModel = ChatViewModel()

    var body: some View {
        VStack {
            TextField("Enter your message", text: $viewModel.userInput)
                .textFieldStyle(RoundedBorderTextFieldStyle())
                .padding()

            Button("Send") {
                Task {
                    await viewModel.sendMessage()
                }
            }
            .disabled(viewModel.isLoading || viewModel.userInput.isEmpty)
            .padding()

            if viewModel.isLoading {
                ProgressView("Thinking...")
            }

            if let error = viewModel.errorMessage {
                Text(error)
                    .foregroundColor(.red)
                    .padding()
            }

            ScrollView {
                Text(viewModel.response)
                    .padding()
            }

            Spacer()
        }
        .padding()
    }
}
```

